"""The one visible 'Generated by Brieflet' line at the end of each generated doc (on by default)."""
from __future__ import annotations

import os

FOOTER = ("<sub>Generated by [Brieflet](https://github.com/Georgesarkis/Brieflet): "
          "short, local-written AI context for code repos.</sub>")


def footer_from_env() -> bool:
    """BRIEFLET_FOOTER=0 (or false/no/off) turns it off."""
    return os.environ.get("BRIEFLET_FOOTER", "1").strip().lower() not in ("0", "false", "no", "off")


def with_footer(txt: str) -> str:
    return txt.rstrip("\n") + "\n\n---\n\n" + FOOTER + "\n"
